import { supabase } from '../lib/supabase';
import type { StorefrontPreviewProduct } from './storefrontImportService';

export type PublicSiteIndexMode = 'page' | 'site';

export type PublicSiteIndexResult = {
  jobId: string;
  sourceUrl: string;
  sourceOrigin: string;
  mode: PublicSiteIndexMode;
  status: 'ready' | 'partial' | 'verified';
  storeName: string;
  products: StorefrontPreviewProduct[];
  warnings: string[];
  pagesDiscovered: number;
  pagesScanned: number;
  productCount: number;
  robotsStatus: 'respected' | 'unavailable' | 'blocked';
  expiresAt: string;
  verifiedAt: string | null;
  workspaceImportId: string | null;
  claimToken?: string;
  verification?: {
    path: string;
    contents: string;
  };
};

export class PublicSiteIndexError extends Error {
  constructor(public code: string, message: string, public status = 400) {
    super(message);
  }
}

const post = async <T>(path: string, body: Record<string, unknown>): Promise<T> => {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const { data } = await supabase.auth.getSession();
  if (!data.session?.access_token) {
    throw new PublicSiteIndexError('AUTH_REQUIRED', 'Sign in with your Wersee account to index a website.', 401);
  }
  headers.Authorization = `Bearer ${data.session.access_token}`;
  const response = await fetch(`/api/storefront-import/${path}`, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  });
  const payload = await response.json().catch(() => null);
  if (!response.ok) {
    throw new PublicSiteIndexError(
      payload?.error?.code || 'PUBLIC_SITE_INDEX_FAILED',
      payload?.error?.message || 'Wersee could not complete this website scan.',
      response.status,
    );
  }
  return payload as T;
};

export const analyzePublicSite = (url: string, mode: PublicSiteIndexMode) =>
  post<PublicSiteIndexResult>('public-analyze', { url, mode, website: '' });

export const restorePublicSiteIndex = (claimToken: string) =>
  post<PublicSiteIndexResult>('public-status', { claimToken });

export const claimPublicSiteIndex = (claimToken: string, verificationToken: string) =>
  post<PublicSiteIndexResult>('public-claim', { claimToken, verificationToken });
